<style scoped lang="scss" src="./tab-divider.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import Switch from "../v-switch/v-switch.vue";


@Component({
  components: {
    "v-switch": Switch,
  }
})
export default class TabDivider extends Vue {
  @Prop({ type: Array, default: () => [] }) tabs;

  curKey = 0;

  clickTab(i) {
    this.curKey = i;
    this.$emit("onTabChange", i);
  }
}
</script>

<template>
  <div class="TabDivider">
    <div class="TabDivider__Line" />
    <div class="TabDivider__Bottom" />
    <div class="TabDivider__Tabs">
      <div
        v-for="(item, i) in tabs"
        :class="{
          TabDivider__Tab: true,
          'TabDivider--selected': i === curKey,
          'TabDivider--unselect': i !== curKey,
        }"
        :key="i"
        @click="clickTab(i)"
      >
        {{ item }}
      </div>
    </div>
    <div class="TabDivider__Slot">
      <v-switch :key="`${curKey}`" :value="`${curKey}`">
        <template v-for="(item, i) in tabs" v-slot:[i]>
          <div :key="i">
            <slot :name="`${curKey}`" />
          </div>
        </template>
      </v-switch>
    </div>
  </div>
</template>
